func New(_ *config.Config, contextName string) Model {
	return Model{
		contextName: contextName,
		runTable: datatable.New(datatable.Config[runRow]{
			Columns: runColumns(),
			// Newest first. A jobs list is read to find out what is happening
			// now, and ascending would pin the session's first run to the top
			// for the rest of the session.
			SortColumn: runColumnStarted,
			SortDesc:   true,
		}),
		itemTable: datatable.New(datatable.Config[itemRow]{
			Columns: itemColumns(),
			// The order the batch was dispatched in. It is the only order that
			// means anything here — the targets of a run have no natural rank,
			// and sorting by state would move a row out from under the cursor
			// every time one settled.
			SortColumn: -1,
		}),
	}
}

// runColumns describes the runs table.
//
// The first column is the run's **state**, not its kind, and it is also where
// the spinner goes. That is the containers table's shape and it is deliberate:
// a jobs list is scanned to find the one that failed and the one still going,
// so the glyph answers the question the reader arrived with, and the Kind
// column says in a word what sort of work it was.
//
// A state glyph column colours by the semantic status styles rather than by a
// theme.IconStyle role, which is the choice the containers table already makes.
// Roles exist for icons that name an *object* — a namespace, a repository, an
// image — where a palette should be able to tell them apart. A state has a
// colour already, and five new roles would give a theme five ways to make
// "failed" not red.
//
// The glyph and the State word are not the redundancy that a glyph beside its
// own name usually is: the glyph column doubles as the spinner while the run
// goes, and the word is what separates the four settled outcomes — "cancelled"
// from "failed" above all, which is the distinction Run.cancelled exists for.
func runColumns() []datatable.Column[runRow] {
	return []datatable.Column[runRow]{
		{
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  func(r runRow) string { return runStateGlyph(r) },
			Style: func(r runRow) lipgloss.Style { return runStateStyle(r.Run.State()) },
		},
		{
			Title: "Kind", Sizing: datatable.SizingFixed, MinWidth: 8,
			Cell: func(r runRow) string { return string(r.Run.Kind) },
			Less: func(a, b runRow) bool { return a.Run.Kind < b.Run.Kind },
			// The state is searchable here rather than through its own column,
			// so `/failed` and `/scan` both work while the glyph column stays
			// out of the filter (Rule 125).
			Search: func(r runRow) string { return string(r.Run.Kind) + " " + string(r.Run.State()) },
		},
		{
			Title: "Label", Sizing: datatable.SizingContent,
			MinWidth: 14, MaxWidth: 40, Flex: 2, TruncateHead: true,
			Cell:   func(r runRow) string { return r.Run.Label },
			Less:   func(a, b runRow) bool { return strings.ToLower(a.Run.Label) < strings.ToLower(b.Run.Label) },
			Search: func(r runRow) string { return r.Run.Label },
		},
		{
			Title: "Progress", Sizing: datatable.SizingFixed, MinWidth: 9,
			Cell: func(r runRow) string { return progressCell(r.Run) },
			// By how far along, not by how many: 1/2 is further than 3/12, and
			// comparing the numerators would rank the bigger batch higher for
			// having more left to do.
			Less: func(a, b runRow) bool { return fraction(a.Run) < fraction(b.Run) },
		},
		{
			Title: "State", Sizing: datatable.SizingFixed, MinWidth: 10,
			Cell:  func(r runRow) string { return string(r.Run.State()) },
			Style: func(r runRow) lipgloss.Style { return runStateStyle(r.Run.State()) },
			Less:  func(a, b runRow) bool { return a.Run.State() < b.Run.State() },
		},
		{
			Title: "Started", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12,
			Cell: func(r runRow) string { return theme.TimeAgo(r.Run.StartedAt) },
			Less: func(a, b runRow) bool { return a.Run.StartedAt.Before(b.Run.StartedAt) },
		},
	}
}

// itemColumns describes one run's targets.
//
// No Started column: an item has no timestamp of its own, and every target of a
// batch shares the run's. What an item has that a run does not is Detail — the
// reason a sync was skipped, the fact a scan failed — and that is what the
// width is worth spending on here.
func itemColumns() []datatable.Column[itemRow] {
	return []datatable.Column[itemRow]{
		{
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  func(r itemRow) string { return itemStateGlyph(r) },
			Style: func(r itemRow) lipgloss.Style { return itemStateStyle(r.Item.State) },
		},
		{
			Title: "Target", Sizing: datatable.SizingContent,
			MinWidth: 20, MaxWidth: 60, Flex: 3, TruncateHead: true,
			Cell:   func(r itemRow) string { return r.Item.Name() },
			Search: func(r itemRow) string { return r.Item.Name() },
		},
		{
			Title: "State", Sizing: datatable.SizingFixed, MinWidth: 10,
			Cell:   func(r itemRow) string { return string(r.Item.State) },
			Style:  func(r itemRow) lipgloss.Style { return itemStateStyle(r.Item.State) },
			Search: func(r itemRow) string { return string(r.Item.State) },
		},
		{
			Title: "Detail", Sizing: datatable.SizingContent, MinWidth: 10, Flex: 2,
			Cell:   func(r itemRow) string { return dashIfEmpty(r.Item.Detail) },
			Style:  func(r itemRow) lipgloss.Style { return detailStyle(r.Item) },
			Search: func(r itemRow) string { return r.Item.Detail },
		},
	}
}

// inventoryScannedStyle colours the scan state: a failure is the one thing in
// this column worth interrupting for, and a target never scanned is dim rather
// than absent.
func inventoryScannedStyle(t scanTarget) lipgloss.Style {
	switch {
	case t.Failed:
		return theme.StatusErrorStyle
	case t.Scanning, !t.Scanned:
		return theme.DimStyle
	}
	// No opinion here: it's the table that sets the theme's text color.
	return lipgloss.NewStyle()
}

// inventoryScannedCell reports the scan state: the spinner while one runs, an
// error icon when the last attempt failed, otherwise how long ago it succeeded
// (Rule 127). Plain text throughout — Rule 122.
func inventoryScannedCell(t scanTarget) string {
	switch {
	case t.Scanning:
		return t.SpinnerFrame + "scanning"
	case t.Failed:
		return theme.IconError + " error"
	case t.Scanned:
		return theme.TimeAgo(t.ScannedAt)
	}
	return "-"
}

// secretsColumnWidth is the Secrets column, held to the width the workspaces
// list gives it. It doesn't sort, and that's deliberate while all its
// neighbors do: `datatable` reserves `title width + 2` for a sortable
// column's arrow, so sorting would cost nine cells to a column that only
// shows a glyph — in the tightest table in the application, where `Target`
// would pay for it at 80 columns.
const secretsColumnWidth = 7

// ciColumnWidth is four cells for one letter: the title is what costs, not the
// value. Same width as the workspaces list gives it.
const ciColumnWidth = 4

// ciColumn is the pipeline grade, and it exists only when scan.enable_ci_score
// is on — off, it would be four cells of nothing on every row.
//
// It does not declare Optional, for the reason the workspaces column does not:
// its states already include two absences that mean different things, and a
// column that vanished on a narrow terminal would add a third that looks like
// them.
//
// It does not sort either. datatable reserves width(title)+2 for a sortable
// column's arrow, which would cost this one six cells instead of four — in the
// narrowest table in the application, where Target pays for it at 80 columns.
func ciColumn() datatable.Column[scanTarget] {
	return datatable.Column[scanTarget]{
		Title: "CI", Sizing: datatable.SizingFixed, MinWidth: ciColumnWidth,
		Cell:  func(t scanTarget) string { return theme.CIScoreCell(t.ci(), t.CIScore) },
		Style: func(t scanTarget) lipgloss.Style { return theme.CIScoreStyle(t.ci(), t.CIScore) },
	}
}

// misconfigColumn is the misconfiguration count, and it exists only when
// scan.categories.misconfig is on — off, it would be a dash on every row for
// the life of the view.
//
// It sits after the four severity counters rather than beside Secrets, where
// the category's verdict arguably belongs: inventoryColumnCritical is an index,
// and slotting a column in front of CRIT would make the column the table opens
// sorted by depend on a setting. Here it joins CI, which is the other column
// answering "what did the scan conclude" rather than "how many CVEs".
//
// It does not declare Optional, for the reason CI does not: its states already
// include an absence, and a column that vanished on a narrow terminal would add
// a second one that looks like it.
func misconfigColumn() datatable.Column[scanTarget] {
	return datatable.Column[scanTarget]{
		Title: "CFG", Sizing: datatable.SizingFixed, MinWidth: countColumnWidth,
		Cell: func(t scanTarget) string {
			return theme.MisconfigCell(t.misconfig(), t.Misconfig.Total(), t.Misconfig.UnrenderedCount() > 0)
		},
		Style: func(t scanTarget) lipgloss.Style {
			return theme.MisconfigStyle(t.misconfig(), t.Misconfig.WorstSeverity())
		},
		// Sortable, unlike CI and Secrets: this is a count, its neighbours sort,
		// and countColumnWidth already covers the width("CFG")+2 a sort arrow
		// asks for.
		Less: func(a, b scanTarget) bool { return a.Misconfig.Total() < b.Misconfig.Total() },
	}
}

// inventoryColumns describes the inventory table.
func inventoryColumns(withCI, withMisconfig bool) []datatable.Column[scanTarget] {
	cols := []datatable.Column[scanTarget]{
		{
			// No title: the column carries a glyph, and a header over it would
			// name something read at a glance anyway. It declares neither Less
			// nor Search — it adds no text anyone could type, so the filter
			// stays on the target's two names.
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  func(t scanTarget) string { return t.kindIcon() },
			Style: func(t scanTarget) lipgloss.Style { return theme.IconStyle(t.kindIconRole()) },
		},
		{
			// Two cells narrower than before on both bounds: the glyph and its
			// space left the cell, so what is measured here is the name alone.
			Title: "Target", Sizing: datatable.SizingContent,
			MinWidth: 22, MaxWidth: 58, Flex: 1, TruncateHead: true,
			Cell: func(t scanTarget) string { return t.shortName() },
			// The cache key, not the alias: an alias is a display name the user
			// can rename, and sorting by it would move every row of a registry
			// the day they do.
			Less: func(a, b scanTarget) bool {
				return strings.ToLower(a.Name) < strings.ToLower(b.Name)
			},
			// Both names. A query for the full path of a repository has to match
			// the row that folds it to "~", and a query for the alias the row
			// actually shows has to match it too — a column saying one name while
			// the search wants the other reads as a bug.
			Search: func(t scanTarget) string { return t.Name + " " + t.Display },
		},
		{
			Title: "Secrets", Sizing: datatable.SizingFixed, MinWidth: secretsColumnWidth,
			Cell:  func(t scanTarget) string { return theme.SecretsIcon(t.secrets()) },
			Style: func(t scanTarget) lipgloss.Style { return theme.SecretsStyle(t.secrets()) },
		},
		countColumn("CRIT", "CRITICAL", func(c scan.SeverityCounts) int { return c.Critical }),
		countColumn("HIGH", "HIGH", func(c scan.SeverityCounts) int { return c.High }),
		countColumn("MED", "MEDIUM", func(c scan.SeverityCounts) int { return c.Medium }),
		countColumn("LOW", "LOW", func(c scan.SeverityCounts) int { return c.Low }),
	}

