1	package workspaces
2	
3	import (
4		"strconv"
5		"strings"
6	
7		tea "github.com/charmbracelet/bubbletea"
8	
9		"github.com/anthnel/devdesk/internal/command"
10		"github.com/anthnel/devdesk/internal/git"
11		"github.com/anthnel/devdesk/internal/jobs"
12		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
13	)
14	
15	// This view's knowledge of what is running is a snapshot the router hands it,
16	// and nothing else (D1). It replaced three maps — scanningPaths, syncingPaths,
17	// deletingPaths — and the syncRun that counted a batch alongside them.
18	//
19	// What the three maps could not do is the whole point: they knew only what this
20	// view had started. A scan launched on the same repository from `:sec` was
21	// invisible to busy(), so the guard let a second one through and the two wrote
22	// the same cache entry. The registry is one bookkeeping, so the guard now
23	// answers for work started anywhere.
24	
25	// scanRun builds the run behind S, A and ctrl+a. Label is what `:jobs` shows,
26	// and the directory being worked in is what identifies the batch to a human.
27	func (m Model) scanRun(targets []string) jobs.Run {
28		return jobs.NewRun(jobs.KindScan, command.ViewWorkspaces, "", m.runLabel(), targets...)
29	}
30	
31	func (m Model) syncRun(targets []string) jobs.Run {
32		return jobs.NewRun(jobs.KindSync, command.ViewWorkspaces, "", m.runLabel(), targets...)
33	}
34	
35	func (m Model) deleteRun(target string) jobs.Run {
36		return jobs.NewRun(jobs.KindDelete, command.ViewWorkspaces, "", pathBaseName(target), target)
37	}
38	
39	// runLabel names a batch by the directory it was launched in.
40	func (m Model) runLabel() string {
41		if m.currentPath != "" {
42			return pathBaseName(m.currentPath)
43		}
44		return pathBaseName(m.getExpandedWorkspacesDir())
45	}
46	
47	// handleJobsChanged takes the router's snapshot. It is the only writer of the
48	// two fields, and there is nothing to reconcile: the snapshot replaces what was
49	// held rather than being merged into it.
50	func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
51		m.jobs = msg.Runs
52		m.jobFrame = msg.Frame
53		m.footer.SetSpinnerFrame(msg.RenderedFrame)
54		m.refreshRows()
55		return m, nil
56	}
57	
58	// liveRuns returns the runs this view is showing: the ones still going, whatever
59	// view started them.
60	//
61	// Not filtered by origin — that is the point. A scan `:sec` launched on a
62	// repository listed here spins on its row, because it is the same repository
63	// and the same work.
64	func (m Model) liveRuns() []jobs.Run {
65		return jobs.Unfinished(m.jobs)
66	}
67	
68	// itemState returns where a target stands in the live runs of a kind, and
69	// whether it is there at all.
70	func (m Model) itemState(kind jobs.Kind, target string) (jobs.ItemState, bool) {
71		for _, run := range m.liveRuns() {
72			if run.Kind != kind {
73				continue
74			}
75			for _, item := range run.Items {
76				if item.Target == target && !item.State.Terminal() {
77					return item.State, true
78				}
79			}
80		}
81		return "", false
82	}
83	
84	// working reports whether a target is queued or running under any kind.
85	func (m Model) working(target string) bool {
86		for _, run := range m.liveRuns() {
87			for _, item := range run.Items {
88				if item.Target == target && !item.State.Terminal() {
89					return true
90				}
91			}
92		}
93		return false
94	}
95	
96	// anyWorking reports whether anything at all is going, which is what decides
97	// whether the footer's progress line carries a spinner.
98	func (m Model) anyWorking() bool { return len(m.liveRuns()) > 0 }
99	
100	// workingKind reports whether a target is queued or running under one kind.
101	func (m Model) workingKind(kind jobs.Kind, target string) bool {
102		_, ok := m.itemState(kind, target)
103		return ok
104	}
105	
106	// scanning, syncing and deleting are the three readings the rows need. They
107	// replace the three maps one for one, and they read the same source.
108	func (m Model) scanning(path string) bool { return m.workingKind(jobs.KindScan, path) }
109	func (m Model) syncing(path string) bool  { return m.workingKind(jobs.KindSync, path) }
110	func (m Model) deleting(path string) bool { return m.workingKind(jobs.KindDelete, path) }
111	
112	// ── The footer line (D9) ─────────────────────────────────────────────────────
113	
114	// jobsStatusLine is what the footer says while work runs. The three forms and
115	// the reason for the third live with the shared implementation
116	// (components.JobsStatusLine) — the dashboard says the same sentence now, and
117	// two copies of a surrender would each be free to surrender differently.
118	func (m Model) jobsStatusLine() string {
119		return sharedcomponents.JobsStatusLine(m.jobs, command.ViewWorkspaces)
120	}
121	
122	// ── What each message tells the registry (jobs.Reporter) ─────────────────────
123	//
124	// The mapping lives here and not in the router: "a sync that was refused
125	// because the tree is dirty is a skip, and the reason is worth keeping" is this
126	// package's vocabulary, and a router that knew it would grow one branch per
127	// view.
128	
129	// syncDetailUpdated marks the one settled outcome the item state cannot carry.
130	// A sync that fast-forwarded and one that had nothing to do are both done; the
131	// summary counts them apart, and this is the only thing that tells them apart.
132	const syncDetailUpdated = "updated"
133	
134	func (m WorkspaceScanStartingMsg) Transition() jobs.Transition {
135		// The cancel goes with the state that says the work started, which is the
136		// only moment there is anything to stop (D7).
137		return jobs.Transition{
138			Kind: jobs.KindScan, Target: m.RepoPath,
139			State: jobs.ItemRunning, Cancel: m.Cancel,
140		}
141	}
142	
143	func (m WorkspaceScanCompleteMsg) Transition() jobs.Transition {
144		t := jobs.Transition{Kind: jobs.KindScan, Target: m.RepoPath, State: jobs.ItemDone}
145		if m.Error != nil {
146			t.State = jobs.ItemFailed
147			t.Detail = "scan failed — check logs"
148		}
149		return t
150	}
151	
152	func (m WorkspaceSyncStartingMsg) Transition() jobs.Transition {
153		return jobs.Transition{Kind: jobs.KindSync, Target: m.RepoPath, State: jobs.ItemRunning}
154	}
155	
156	func (m WorkspaceSyncCompleteMsg) Transition() jobs.Transition {
157		t := jobs.Transition{Kind: jobs.KindSync, Target: m.RepoPath, State: jobs.ItemDone}
158		switch {
159		case m.Error != nil:
160			t.State = jobs.ItemFailed
161			t.Detail = "sync failed — check logs"
162		case m.Outcome == git.SyncSkipped:
163			// A refusal is not a failure: the fetch happened, the merge did not,
164			// and the reason is what the summary names one repository by.
165			t.State = jobs.ItemSkipped
166			t.Detail = m.Reason
167		case m.Outcome == git.SyncUpdated:
168			t.Detail = syncDetailUpdated
169		}
170		return t
171	}
172	
173	func (m EntryDeletedMsg) Transition() jobs.Transition {
174		t := jobs.Transition{Kind: jobs.KindDelete, Target: m.Path, State: jobs.ItemDone}
175		if m.Error != nil {
176			t.State = jobs.ItemFailed
177			t.Detail = "delete failed — check logs"
178		}
179		return t
180	}
181	
182	// Compile-time proof that every progress message this view emits can be applied
183	// to the registry. A message added without one would be routed, would update
184	// the view, and would leave its row spinning for the life of the view — which
185	// is precisely the failure the registry exists to remove.
186	var (
187		_ jobs.Reporter = WorkspaceScanStartingMsg{}
188		_ jobs.Reporter = WorkspaceScanCompleteMsg{}
189		_ jobs.Reporter = WorkspaceSyncStartingMsg{}
190		_ jobs.Reporter = WorkspaceSyncCompleteMsg{}
191		_ jobs.Reporter = EntryDeletedMsg{}
192	)
193	
194	// ── The sync summary ─────────────────────────────────────────────────────────
195	
196	// syncSummary is what the footer says once a sync batch has settled.
197	//
198	// It is posted as a footer message rather than derived like the progress line,
199	// and the difference is Rule 128's own: progress is a state, which is why it
200	// cannot carry a timer, and an outcome is an event, which is exactly what a
201	// footer message is. The old code derived both from one struct because they
202	// shared a function; once progress comes from the registry, they stop needing
203	// to be the same thing.
204	func (m Model) syncSummary(run jobs.Run) string {
205		var updated, upToDate, skipped, failed int
206		var firstSkipped, firstSkippedReason, firstFailed string
207	
208		for _, item := range run.Items {
209			switch {
210			case item.State == jobs.ItemFailed:
211				failed++
212				if firstFailed == "" {
213					firstFailed = pathBaseName(item.Target)
214				}
215			case item.State == jobs.ItemSkipped:
216				// A cancellation lands here too, and its Detail says so: the
217				// registry writes "cancelled" on an item that never ran, which
218				// reads correctly in "1 skipped (api: cancelled)".
219				skipped++
220				if firstSkipped == "" {
221					firstSkipped = pathBaseName(item.Target)
222					firstSkippedReason = item.Detail
223				}
224			case item.Detail == syncDetailUpdated:
225				updated++
226			default:
227				upToDate++
228			}
229		}
230	
231		var parts []string
232		if updated > 0 {
233			parts = append(parts, sharedcomponents.Plural(updated, "repository", "repositories")+" updated")
234		}
235		if upToDate > 0 {
236			parts = append(parts, strconv.Itoa(upToDate)+" up to date")
237		}
238		if skipped > 0 {
239			parts = append(parts, strconv.Itoa(skipped)+" skipped ("+firstSkipped+": "+firstSkippedReason+")")
240		}
241		if failed > 0 {
242			parts = append(parts, strconv.Itoa(failed)+" failed ("+firstFailed+") — check logs")
243		}
244		if m.syncMovedTags > 0 {
245			parts = append(parts, sharedcomponents.Plural(m.syncMovedTags, "tag", "tags")+" moved ("+m.syncFirstMovedTag+")")
246		}
247		if m.syncUnreadable > 0 {
248			parts = append(parts, sharedcomponents.Plural(m.syncUnreadable, "directory", "directories")+" unreadable — check logs")
249		}
250		if len(parts) == 0 {
251			return "Nothing to sync"
252		}
253		return strings.Join(parts, " · ")
254	}
